package app.layan.quran;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;

/** Shared Layan identity for the independent Hadith and prayer screens. */
public abstract class LayanBaseActivity extends Activity {
 protected LinearLayout root,body;protected int background,paper,ink,muted,green,border;protected boolean dark;protected android.content.SharedPreferences prefs;protected Typeface font;
 @Override protected void onCreate(Bundle state){boolean night=android.preference.PreferenceManager.getDefaultSharedPreferences(this).getBoolean("nightMode",false);int theme=getResources().getIdentifier(night?"LayanNativeDark":"LayanNativeLight","style",getPackageName());if(theme!=0)setTheme(theme);super.onCreate(state);prefs=getSharedPreferences("layan_local",0);LayanUi.Palette colors=new LayanUi.Palette(this);dark=colors.dark;background=colors.background;paper=colors.paper;ink=colors.ink;muted=colors.muted;green=colors.green;border=colors.border;font=Typeface.create("sans-serif",Typeface.NORMAL);}
 protected void frame(String title,String caption){root=column();root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(background);getWindow().setStatusBarColor(background);getWindow().setNavigationBarColor(background);getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(root);LinearLayout header=row();header.setPadding(dp(12),dp(8),dp(14),dp(10));Button back=button("›",()->finish());back.setContentDescription("رجوع");header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout titles=column();titles.addView(label(title,27,ink));if(!caption.isEmpty())titles.addView(label(caption,13,muted));header.addView(titles,new LinearLayout.LayoutParams(0,-2,1));ImageView logo=new ImageView(this);logo.setImageResource(getResources().getIdentifier("ic_launcher","mipmap",getPackageName()));logo.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);LinearLayout.LayoutParams iconParams=new LinearLayout.LayoutParams(dp(40),dp(40));iconParams.setMargins(dp(10),0,dp(4),0);header.addView(logo,iconParams);((TextView)titles.getChildAt(0)).setTypeface(Typeface.create("sans-serif",Typeface.BOLD));((TextView)titles.getChildAt(0)).setTextSize(23);root.addView(header);body=column();root.addView(body,new LinearLayout.LayoutParams(-1,0,1));root.requestApplyInsets();}
 @Override protected void onResume(){super.onResume();if(new LayanUi.Palette(this).dark!=dark)recreate();}
 protected LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 protected LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 protected TextView label(String s,float size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(font);t.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG_RTL);return t;}
 protected Button button(String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(15);b.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));boolean filled=text.length()>2&&!text.contains("تحميل");b.setTextColor(filled?Color.WHITE:green);b.setBackground(LayanUi.button(this,filled));b.setMinHeight(dp(44));b.setElevation(dp(2));b.setOnClickListener(v->action.run());return b;}
 protected android.graphics.drawable.Drawable cardBackground(int c){return LayanUi.panel(this,c);}
 protected LinearLayout card(){LinearLayout l=column();l.setPadding(dp(18),dp(16),dp(18),dp(16));l.setBackground(cardBackground(paper));return l;}
 protected int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 protected void gap(LinearLayout l,int n){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(n)));}
 protected void toast(String t){Toast.makeText(this,t,Toast.LENGTH_SHORT).show();}
 protected static String digits(String s){StringBuilder b=new StringBuilder();for(char c:s.toCharArray())b.append(c>='0'&&c<='9'?(char)('٠'+c-'0'):c);return b.toString();}
}
